import{_ as t,a as e}from"./chunks/dochazka_typ.DsSXJvoi.js";import{_ as a,o as n,c as s,aa as d}from"./chunks/framework.BAs_AphD.js";const r="/buildary-help-preview/media/cs/diary/dochazka_convision.webp",i="/buildary-help-preview/media/cs/diary/dochazka_sysdo.webp",l="/buildary-help-preview/media/cs/diary/import_dochazky2.png",b=JSON.parse('{"title":"Docházkový systém","description":"","frontmatter":{"title":"Docházkový systém","wiki":"cs:diary:attendance_system"},"headers":[],"relativePath":"diary/attendance_system.md","filePath":"diary/attendance_system.md","lastUpdated":1795418046000}'),p={name:"diary/attendance_system.md"};function y(v,o,m,u,h,k){return n(),s("div",null,[...o[0]||(o[0]=[d('<h1 id="dochazkovy-system" tabindex="-1">Docházkový systém <a class="header-anchor" href="#dochazkovy-system" aria-label="Permalink to &quot;Docházkový systém&quot;">​</a></h1><p>Eviduje-li vaše firma příchody a odchody pracovníků v docházkovém systému, Buildary z něj načte jmenný seznam osob na staveništi rovnou do denního záznamu. Na větších stavbách je to prakticky jediná reálná cesta, jak splnit požadavek vyhlášky 131/2024 Sb. (příloha 12) na jmenovitý seznam osob na stavbě.</p><p>Napojení si nastavíte sami: docházkový systém nejdřív přidáte do <a href="/buildary-help-preview/firstofall/domain">firemní domény</a> a pak ho v každém deníku vyberete. Na jedné doméně může být napojeno i víc systémů – třeba když každá stavba používá jiný.</p><p>Krok za krokem: <a href="/buildary-help-preview/akademie/napojeni">Napojit docházku nebo čidla</a> v Akademii.</p><h2 id="podporovane-systemy" tabindex="-1">Podporované systémy <a class="header-anchor" href="#podporovane-systemy" aria-label="Permalink to &quot;Podporované systémy&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Docházkový systém</th><th>Přístupové údaje</th></tr></thead><tbody><tr><td><strong>Convision</strong>, <strong>AdamAssistant</strong>, <strong>Fingera</strong></td><td>uživatelské jméno a heslo</td></tr><tr><td><strong>Sysdo</strong>, <strong>Sysdo seskupené</strong>, <strong>WinPak</strong></td><td>API klíč</td></tr></tbody></table><p>Přístupové údaje vám dá dodavatel docházkového systému. O napojení jiného systému nám napište na <a href="mailto:buildary@firstis.eu" target="_blank" rel="noreferrer">buildary@firstis.eu</a>.</p><h2 id="co-budete-potrebovat" tabindex="-1">Co budete potřebovat <a class="header-anchor" href="#co-budete-potrebovat" aria-label="Permalink to &quot;Co budete potřebovat&quot;">​</a></h2><ul><li>V doméně právo <strong>Administrace domény</strong> – bez něj záložku <strong>Nastavení docházky</strong> neuvidíte. Viz <a href="/buildary-help-preview/diary/userpermissions">Kdo co smí v deníku</a>.</li><li>Přístupové údaje do docházkového systému (viz tabulka výše).</li><li>Pro výběr systému v deníku kompetenci <strong>Administrace deníku</strong>.</li></ul><h2 id="pridat-dochazkovy-system-do-domeny" tabindex="-1">Přidat docházkový systém do domény <a class="header-anchor" href="#pridat-dochazkovy-system-do-domeny" aria-label="Permalink to &quot;Přidat docházkový systém do domény&quot;">​</a></h2><ol><li>V levém panelu klikněte na ikonu glóbu (<strong>Seznam domén</strong>) a doménu otevřete ikonou tužky.</li><li>Přejděte na záložku <strong>Nastavení docházky</strong> a klikněte na <strong>Nový docházkový systém</strong>.</li><li>Vyberte <strong>Typ docházky</strong> a vyplňte <strong>Název napojení</strong>.</li><li>Doplňte přístupové údaje a klikněte na <strong>Uložit</strong>.</li></ol><figure class="shot" style="--w:652px;"><img src="'+t+'" alt="Záložka Nastavení docházky v detailu domény s tlačítkem Nový docházkový systém a prázdným seznamem napojení" loading="lazy"></figure><figure class="shot" style="--w:376px;"><img src="'+e+'" alt="Dialog Nový docházkový systém s rozbaleným seznamem Typ docházky: Convision, Sysdo, WinPak, Sysdo seskupené, AdamAssistant, Fingera" loading="lazy"><figcaption>Výběr typu docházky.</figcaption></figure><p>Podle typu docházky se v okně objeví pole pro jméno a heslo, nebo pro API klíč:</p><div class="shots"><figure class="shot" style="--w:330px;"><img src="'+r+'" alt="Dialog pro Convision s poli Název napojení, Uživatelské jméno a Heslo" loading="lazy"><figcaption>Convision: jméno a heslo.</figcaption></figure><figure class="shot" style="--w:330px;"><img src="'+i+'" alt="Dialog pro Sysdo s poli Název napojení a API klíč" loading="lazy"><figcaption>Sysdo: API klíč.</figcaption></figure></div><div class="tip custom-block"><p class="custom-block-title">Jak napojení pojmenovat</p><p>Pod <strong>Názvem napojení</strong> systém uvidíte při výběru v deníku. Zvolte ho tak, aby se systémy daly snadno rozlišit, například „Sysdo – Ostrava“ a „Convision – Brno“.</p></div><h3 id="kontrola-pri-ulozeni" tabindex="-1">Kontrola při uložení <a class="header-anchor" href="#kontrola-pri-ulozeni" aria-label="Permalink to &quot;Kontrola při uložení&quot;">​</a></h3><p>Po kliknutí na <strong>Uložit</strong> Buildary údaje nejen uloží, ale také zkusí váš docházkový systém zavolat:</p><ul><li><strong>Povede se</strong> – okno se zavře a zobrazí se potvrzení.</li><li><strong>Nepovede se</strong> – okno zůstane otevřené s hláškou „Nastal problém při volání docházkového systému. Zkontrolujte zadané údaje.“ Opravte údaje a uložte znovu.</li></ul><p>Nevyplněná povinná pole jsou označená textem „Toto pole je povinné.“</p><h3 id="stavby-s-ruznymi-systemy" tabindex="-1">Stavby s různými systémy <a class="header-anchor" href="#stavby-s-ruznymi-systemy" aria-label="Permalink to &quot;Stavby s různými systémy&quot;">​</a></h3><p>Přidejte do domény víc napojení a v každém deníku vyberte to správné. Stavbu kvůli jinému docházkovému systému už není nutné přesouvat do jiné domény.</p><h2 id="upravit-nebo-odstranit-napojeni" tabindex="-1">Upravit nebo odstranit napojení <a class="header-anchor" href="#upravit-nebo-odstranit-napojeni" aria-label="Permalink to &quot;Upravit nebo odstranit napojení&quot;">​</a></h2><ul><li><strong>Upravit</strong> – v seznamu na záložce <strong>Nastavení docházky</strong> napojení otevřete a změňte název, typ nebo přístupové údaje. Uložené heslo ani API klíč se z bezpečnostních důvodů nezobrazují; když je při úpravě nevyplníte, zůstane uložená původní hodnota.</li><li><strong>Odstranit</strong> – napojení, které některý deník používá, odstranit nejde. Nejdřív v tom deníku nastavte jiný systém, nebo docházku vypněte.</li></ul><h2 id="vybrat-dochazkovy-system-v-deniku" tabindex="-1">Vybrat docházkový systém v deníku <a class="header-anchor" href="#vybrat-dochazkovy-system-v-deniku" aria-label="Permalink to &quot;Vybrat docházkový systém v deníku&quot;">​</a></h2><p>Otevřete <a href="/buildary-help-preview/diary/diarysettings">Nastavení deníku</a>, záložku <strong>Základní</strong>. Část s docházkou se zobrazí, jen když je na doméně stavby aspoň jedno napojení a máte kompetenci <strong>Administrace deníku</strong>.</p><ol><li>Vyberte <strong>docházkový systém</strong> – nabízejí se napojení pod názvy z nastavení domény.</li><li>Vyberte terminál (stavbu) z nabídky daného systému. U <strong>Sysdo</strong> a <strong>Sysdo seskupené</strong> místo toho zadáte identifikátor stavby do textového pole.</li><li>Volitelně vyplňte <strong>Filtruj IČO dodavatelů</strong> – načtou se jen osoby těchto firem, ostatní se odfiltrují. Prázdné pole načítá všechny.</li><li>Nastavení uložte.</li></ol><p>Volba <strong>Všechny</strong> terminály je jen u systému Sysdo.</p><h2 id="nacist-dochazku-do-deniku" tabindex="-1">Načíst docházku do deníku <a class="header-anchor" href="#nacist-dochazku-do-deniku" aria-label="Permalink to &quot;Načíst docházku do deníku&quot;">​</a></h2><p>V denním záznamu se v sekci <strong>Osoby na staveništi</strong> objeví tlačítko <strong>Import docházky</strong> s nabídkou:</p><table tabindex="0"><thead><tr><th>Volba</th><th>Co udělá</th></tr></thead><tbody><tr><td><strong>Import docházky</strong></td><td>Načte docházku daného dne podle nastavení deníku.</td></tr><tr><td><strong>Import docházky s výběrem</strong></td><td>Nejdřív zobrazí firmy, které mají v daném dni na stavbě aspoň jednoho pracovníka. Zaškrtněte ty, jejichž docházku chcete načíst.</td></tr></tbody></table><p>Import s výběrem se hodí, když vedete deník jen na část stavby, ale docházkový terminál je společný pro celou stavbu.</p><figure class="shot" style="--w:640px;"><img src="'+l+'" alt="Sekce Osoby na staveništi s rozbaleným tlačítkem Import docházky" loading="lazy"></figure><p>Záznamy načtené z docházkového systému jsou označené ikonou, takže je snadno odlišíte od ručně zadaných. Z jakého systému záznam pochází, ikona neuvádí.</p><p>Jak se se záznamy o osobách pracuje dál, popisuje stránka <a href="/buildary-help-preview/diary/dailyentriespersons">Počasí, osoby, stroje a materiály</a>.</p><h2 id="kdyz-neco-nejde" tabindex="-1">Když něco nejde <a class="header-anchor" href="#kdyz-neco-nejde" aria-label="Permalink to &quot;Když něco nejde&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Potíž</th><th>Co s tím</th></tr></thead><tbody><tr><td>Nevidím záložku <strong>Nastavení docházky</strong>.</td><td>Nemáte v doméně právo <strong>Administrace domény</strong>. Požádejte administrátora domény.</td></tr><tr><td>V Nastavení deníku chybí část s docházkou.</td><td>Na doméně stavby zatím není žádné napojení, nebo nemáte v deníku kompetenci <strong>Administrace deníku</strong>.</td></tr><tr><td>Napojení nejde uložit.</td><td>Zkontrolujte přístupové údaje a jestli je docházkový systém dostupný. Případně se obraťte na jeho dodavatele.</td></tr><tr><td>Napojení nejde odstranit.</td><td>Používá ho některý deník. V nastavení toho deníku nejdřív vyberte jiný systém nebo docházku vypněte.</td></tr></tbody></table><p>Nevíte si rady? Napište na <a href="mailto:buildary@firstis.eu" target="_blank" rel="noreferrer">buildary@firstis.eu</a>.</p>',38)])])}const g=a(p,[["render",y]]);export{b as __pageData,g as default};
